const main=document.getElementById('main');
const fb='https://www.facebook.com/profile.php?id=100094159502968';
const yt='https://www.youtube.com/@travelthebackroads';
const intro=(label,title,description='')=>`<section class="page-top"><div class="wrap"><p class="eyebrow">${label}</p><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div></section>`;
const storyCard=()=>`<article class="feature"><img src="assets/sarande.jpg" alt="The waterfront and hills of Sarandë, Albania"><div class="feature-copy"><span class="meta">Albania · Our travel journal</span><h3><a href="#/ten-suitcases">Ten suitcases.<br>One new beginning.</a></h3><p>We sold almost everything, hugged our family goodbye, and headed for Albania. A week on an air mattress may have helped with the timing.</p><a class="text-link" href="#/ten-suitcases">Read our Sarandë story →</a></div></article>`;
const pages={
'/':()=>`<section class="hero"><div class="hero-inner"><p class="eyebrow">ROBERT & BRENDA · TRAVEL THE BACK ROADS</p><h1>A little off the beaten path.<br>A lot to discover.</h1><p>Real places. Good stories. Unexpected detours.<br>Come along as we travel with a purpose—and keep our sense of humor handy.</p><a class="button" href="#/blog">COME ALONG FOR THE RIDE →</a></div><span class="hero-note">CURRENT CHAPTER: SARANDË, ALBANIA</span></section><div class="trail"><span>Take the scenic route</span><span>Meet the people</span><span>Bring your sense of humor</span></div><section class="section wrap"><div class="section-head"><div><p class="eyebrow">POSTCARDS FROM THE ROAD</p><h2>Our latest chapter</h2></div><a href="#/blog" class="text-link">The travel journal →</a></div>${storyCard()}</section><section class="purpose-band"><div class="wrap section split"><div><p class="eyebrow">MORE THAN A PLACE ON THE MAP</p><h2>Travel with a purpose.</h2><p>For us, the journey is about more than the view. It’s about faith, connection, and making room for the people and stories we meet along the way.</p><a class="text-link" href="#/purpose">The heart behind the journey →</a></div><div class="quote">“They knew where they were going.<br>We’re still learning!”<small>— BRENDA, ON OUR FIRST RIDE BACK TO SARANDË</small></div></div></section><section class="section wrap"><div class="section-head"><div><p class="eyebrow">WHERE THE ROAD HAS TAKEN US</p><h2>Start with Albania</h2></div><a class="text-link" href="#/destinations">Explore destinations →</a></div><a class="destination" href="#/albania"><img loading="lazy" src="assets/sarande.jpg" alt="Sarandë curving around the Ionian Sea"><div class="overlay"><p>EUROPE / ALBANIAN RIVIERA</p><h3>Sarandë, Albania</h3><p>Sea views, new beginnings, and a guy who knows a guy. →</p></div></a></section><section class="hello"><p class="eyebrow">HELLO FROM THE BACK ROADS</p><h2>We’re Robert & Brenda.</h2><p>Travelers, storytellers, and believers that the best adventures often start with an unexpected turn. We’re glad you’re here.</p><a class="button outline" href="#/about">A LITTLE ABOUT US →</a></section>`,
'/blog':()=>intro('THE TRAVEL JOURNAL','Stories worth taking the long way for.','A little adventure, a little humor, and the honest details that never quite make it onto a postcard.')+`<section class="wrap section">${storyCard()}<p class="small" style="margin-top:24px">Our journal begins here. More stories from the back roads will follow.</p></section>`,
'/purpose':()=>intro('THE HEART OF THE JOURNEY','Travel with a Purpose','The places matter. So do the people we meet along the way.')+`<div class="wrap"><article class="prose"><p>When we packed up our life and returned to Albania, we brought more than ten suitcases. We brought a desire to travel with a purpose.</p><h2>Faith. Connection. An open heart.</h2><p>Back in Sarandë, we’ve started attending our church, Kisha Jeta Triumfale, again. Returning to a familiar church has been part of finding our rhythm and feeling at home.</p><p>We’re still putting into words the longer story of how we came to this point, and what purposeful travel means for us. We look forward to sharing that story here.</p><div class="quote">A new place to call home.<br>A purpose still unfolding.</div><h2>Come along as the story grows.</h2><p>For now, our first chapter begins with saying goodbye, letting go of belongings, and making room for something new.</p><a class="button" href="#/ten-suitcases">READ OUR FIRST CHAPTER →</a></article></div>`,
'/destinations':()=>intro('PLACES & CHAPTERS','Where shall we go?','Our stories begin in Albania, with family and memories back home in the United States.')+`<section class="wrap section"><a class="destination" href="#/albania"><img src="assets/sarande.jpg" alt="Sarandë waterfront"><div class="overlay"><p>EUROPE</p><h3>Albania</h3><p>Our current home base. Explore the story →</p></div></a><div class="notice"><span class="meta">BACK HOME · UNITED STATES</span><h3>The road to goodbye</h3><p>Family visits in Idaho and Delaware, goodbyes to our siblings and parents, and a departure from Pennsylvania. The beginning of our Albania adventure is a story of home, too.</p><a class="text-link" href="#/ten-suitcases">Read how it all began →</a></div></section>`,
'/albania':()=>intro('DESTINATIONS / ALBANIA','Our Albanian chapter','We lived in Sarandë from February through May 2026. On September 11, we returned—with ten suitcases and a new beginning.')+`<section class="wrap section">${storyCard()}<div class="notice"><h3>Our home by the sea</h3><p>We’re settling into a sea-facing apartment in Building Zero Zero. After our temporary apartment at the back of the building, we can finally hear the waves.</p><a href="#/gallery" class="text-link">A glimpse of Sarandë →</a></div></section>`,
'/gallery':()=>intro('A GLIMPSE OF THE JOURNEY','The view from here.','A little inspiration from the place we’re calling home.')+`<section class="wrap section"><button class="gallery-button" id="expand-photo" aria-label="Enlarge panoramic photograph of Sarandë"><img class="gallery-img" src="assets/sarande.jpg" alt="Wide panorama of Sarandë’s waterfront and the Ionian Sea"></button><div class="caption"><div><h3>Sarandë, Albania</h3><p class="small">Click the image to take a closer look.</p></div><p class="small">Destination reference photograph by paisaman37.<br><a class="text-link" href="#/credits">View photo credits →</a></p></div><div class="notice"><h3>Our own photo album is next.</h3><p>We’ll be adding personal photographs from our travels. For now, this credited panorama offers a glimpse of Sarandë.</p></div></section>`,
'/about':()=>intro('MEET YOUR TRAVEL COMPANIONS','Hello! We’re Robert & Brenda.','Travelers, storytellers, and publishers taking the scenic route.')+`<div class="wrap"><article class="prose"><p>We believe the best adventures happen off the beaten path. Through our journeys across the USA and Europe, we uncover hidden gems, savor memorable meals, and share the stories that make each place special.</p><h2>Less stuff. More stories.</h2><p>In 2026, we rented out our house and sold just about everything we owned. The treasures we kept fit into a 5-by-5-by-8-foot storage unit. Everything else? Yard sales, Facebook Marketplace, and some very helpful neighbors.</p><p>We returned to Sarandë, Albania, on September 11 with ten suitcases. We’d already lived here earlier in the year, and this time we came back to begin a new chapter.</p><h2>Travel. Discover. Write. Inspire.</h2><p>Our interests stretch from travel and food reviews to video storytelling and book publishing. We’re developing our <em>Travel the Back Roads Crime Mysteries</em> series, including <em>Death on the Falkirk Wheel</em>, set in Scotland, and our children’s series, <em>The Adventures of Noel & George</em>.</p><p>Here, we’re starting with our own travel journal: the goodbyes, the sea views, and the moments that make us laugh along the way.</p><a class="button" href="#/ten-suitcases">GET TO KNOW OUR STORY →</a></article></div>`,
'/contact':()=>intro('LET’S KEEP IN TOUCH','Say hello from your corner of the world.','Have a travel story, a question, or a back road we should know about? We’d love to hear from you.')+`<section class="wrap section"><div class="contact-grid"><div class="contact-card"><span class="meta">CONVERSATIONS & UPDATES</span><h2>Find us on Facebook</h2><p>Follow our updates and reach out through our Facebook page.</p><a class="button" href="${fb}" target="_blank" rel="noopener">VISIT OUR FACEBOOK ↗</a></div><div class="contact-card"><span class="meta">A LITTLE MOTION, A LITTLE HUMOR</span><h2>Come along on YouTube</h2><p>Join us for travel clips and stories from the road.</p><a class="button outline" href="${yt}" target="_blank" rel="noopener">WATCH ON YOUTUBE ↗</a></div></div></section>`,
'/credits':()=>intro('THE DETAILS','Photo credits')+`<div class="wrap"><article class="prose"><h2>Sarandë panorama</h2><p><a href="https://commons.wikimedia.org/wiki/File:Panorama_Photography_of_Saranda.jpg" target="_blank" rel="noopener">Panorama Photography of Saranda</a> by paisaman37, July 7, 2016, via Wikimedia Commons. Licensed under <a href="https://creativecommons.org/licenses/by-sa/2.0/" target="_blank" rel="noopener">Creative Commons Attribution–ShareAlike 2.0</a>.</p><p>The image is displayed with responsive cropping. The photograph and any adapted crop remain available under the same license. This is a destination reference image, not a personal photograph by Robert and Brenda.</p><h2>Our logo</h2><p>Travel the Back Roads logo supplied through our existing website.</p></article></div>`,
'/ten-suitcases':()=>intro('ALBANIA · OCTOBER 28, 2026','Ten suitcases and a new beginning','By Brenda & Rob · Our return to Sarandë')+`<div class="wrap"><article class="prose"><img class="article-image" src="assets/sarande.jpg" alt="Panoramic view of Sarandë"><p class="small">Sarandë reference photograph by paisaman37 · <a href="#/credits">Photo credits</a></p><p>Hello, family and friends!</p><p>We’ve been back in Sarandë, Albania, for about a month and a half now. We arrived on September 11, 2026, with ten suitcases, a whole lot of anticipation, and plenty of goodbyes still tugging at our hearts.</p><p>Before we tell you about life by the sea, we should probably tell you how we got here!</p><h2>How do you pack up a life?</h2><p>Apparently, one yard sale at a time.</p><p>We rented out our house and sold just about everything we owned. What remains back home fits into a 5-by-5-by-8-foot storage unit: treasures from our children, their artwork and school projects, and our favorite Christmas tree ornaments. The things we simply couldn’t part with.</p><p>My Le Creuset pots and pans and Fiesta dinnerware went to my daughter-in-law. I’m happy they stayed in the family, but yes, there may have been tears. Those pots deserved a proper goodbye, too!</p><p>A huge thank-you goes to our neighbor Ellen, who helped us sell our belongings and kept me focused. Naturally, I wanted top dollar for everything. Ellen finally asked, “Do you want to get rid of it, or do you want to make money?”</p><p>Right. We were trying to get rid of it. Apparently, I had been conducting an estate sale with museum pricing.</p><p>Our larger items went on Facebook Marketplace, which worked out really well once we explained to buyers that we were moving to Albania. Little by little, the house emptied, and this adventure began to feel very real.</p><h2>The hardest goodbyes</h2><p>Before leaving, we made the rounds to spend time with family.</p><p>We drove out to Idaho to visit our son, daughter-in-law, and grandchild, and spent time with our other son, daughter-in-law, and two grandchildren in Delaware. There were big hugs, lots of kisses, and the kind of goodbyes you wish you could stretch just a little longer.</p><p>We also said goodbye to our siblings and our parents in New Jersey, Pennsylvania, and Maryland.</p><p>Selling furniture is one thing. Saying goodbye to the people you love is something else entirely.</p><h2>Ten suitcases and a one-way adventure</h2><p>Our original plan was to return to Albania on October 1, when our apartment rental began. But we’d rented out our house, sold just about everything, and spent a week sleeping on an air mattress.</p><p>We couldn’t take it any longer. Apparently, our sense of adventure does not extend to getting up off the floor every morning.</p><p>So we moved our departure up to September 10. Albania was calling—and so was a real bed.</p><p>We hired a driver to take us from Pottstown, Pennsylvania, to Newark Airport. From there, we flew to London, then on to Tirana, Albania, followed by about four hours on the road south to Sarandë.</p><p>And yes, we brought <strong>ten suitcases</strong>.</p><p>ChatGPT said bringing our clothing would be cheaper than replacing it. So there we were, putting that advice to the test—and needing a very large vehicle on the other end.</p><p>Fortunately, having already lived in Sarandë from February through May earlier this year, we knew a guy.</p><p>Our guy was Danny.</p><p>Danny wasn’t picking us up himself, but Danny knew a guy. And that guy met us at the airport with a van that could seat about twenty people.</p><p>There was plenty of room for our suitcases—and, as it turned out, a small business opportunity.</p><h2>“Do you want to make some money?”</h2><p>With all those empty seats, our new driver asked whether we wanted to make some money by picking up passengers along the way to Sarandë.</p><p>If this had been our first rodeo, we might have been a little nervous. But we’d been here before. Sure! Apparently, we were in the transportation business now.</p><p>People waited along the roadside, climbed aboard, and let the driver know when they wanted to get off. Sometimes we couldn’t see a house or village anywhere. Someone would simply step out in what looked to us like the middle of nowhere.</p><p>They knew where they were going. We’re still learning!</p><p>We made <strong>1,000 lek</strong> from the passengers we picked up along the way. We might have made more, but the driver missed a few potential customers because he was busy smoking and talking on the phone. Passenger recruitment was clearly something he fit in between his other activities.</p><p>Unfortunately, my black linen Talbots blazer stayed on the bus when we got off.</p><p>We texted “the guy” a few times, but he never responded.</p><p>Maybe he isn’t our guy after all.</p><p>So, our first Albanian business venture earned us 1,000 lek—about $10—and cost me a $150 blazer. I’m still working out the accounting.</p><h2>Back to Building Zero Zero</h2><p>After the long journey, we arrived at Building Zero Zero, the same apartment building where we stayed from February through May. Several other Americans live here, too, and the building sits right on the sea.</p><p>During our earlier stay, our apartment was on the side of the building. This time, we had rented one at the front, overlooking the water, beginning October 1.</p><p>Arriving early meant we needed somewhere to stay from September 11 until then. Thank God, an apartment was available in the same building for those exact dates!</p><p>That temporary apartment was at the back, facing another building, with a side view of the sea. We could catch a glimpse of the water, but we couldn’t hear the waves crashing onto the shore.</p><p>Now we’re in our sea-facing apartment, and we can hear them.</p><p>After all the sorting, selling, packing, traveling, and goodbyes, hearing the sea from our home feels especially sweet.</p><h2>Finding our rhythm again</h2><p>We’ve also started attending our church, Kisha Jeta Triumfale, again. Returning to a familiar church has been part of settling back into life here.</p><p>There’s more we want to share about how Rob and I came to this point—and why we wanted to travel with a purpose. That story deserves a little room of its own.</p><p>For now, picture us here in Sarandë: unpacked, settling in, listening to the waves, and missing the people we love.</p><p>And if you happen to see someone in a lovely black Talbots blazer driving a twenty-passenger van, please tell him we’ve been trying to reach him.</p><p>With love from Albania,<br>Rob and Brenda</p><a class="text-link" href="#/blog">← Back to the journal</a></article></div>`
};
const titles={'/':'Home','/blog':'Blog','/purpose':'Travel with a Purpose','/destinations':'Destinations','/albania':'Albania','/gallery':'Gallery','/about':'About','/contact':'Contact','/credits':'Photo credits','/ten-suitcases':'Ten suitcases and a new beginning'};
function render(){let route=location.hash.slice(1)||'/';main.innerHTML=pages[route]?pages[route]():intro('A SMALL DETOUR','This road doesn’t lead anywhere yet.')+'<div class="wrap section"><a class="button" href="#/">BACK HOME →</a></div>';document.title=(titles[route]||'Page not found')+' | Travel the Back Roads';document.querySelectorAll('nav a').forEach(a=>{let r=a.hash.slice(1);const active=r===route||(r==='/blog'&&route==='/ten-suitcases')||(r==='/destinations'&&route==='/albania');if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('nav').classList.remove('open');document.getElementById('menu').setAttribute('aria-expanded','false');document.getElementById('expand-photo')?.addEventListener('click',()=>document.getElementById('lightbox').showModal());window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{render();main.focus({preventScroll:true})});render();
document.getElementById('menu').addEventListener('click',e=>{const open=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.setAttribute('aria-label',open?'Close navigation':'Open navigation')});
const search=document.getElementById('search'),query=document.getElementById('query'),results=document.getElementById('results');const index=Object.entries(titles).filter(([r])=>r!='/credits').map(([route,title])=>({route,title,text:pages[route]().replace(/<[^>]*>/g,' ').toLowerCase()}));
function searchNow(){const q=query.value.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const matches=index.filter(item=>!q||(item.title+' '+item.text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q));results.replaceChildren();if(!matches.length){results.textContent='No matches yet. Try Albania, family, or purpose.';return}matches.forEach(item=>{const a=document.createElement('a');a.href='#'+item.route;a.textContent=item.title+' →';a.addEventListener('click',()=>search.close());results.appendChild(a)})}
document.querySelector('.search-toggle').addEventListener('click',()=>{search.showModal();searchNow();query.focus()});query.addEventListener('input',searchNow);document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();search.showModal();searchNow();query.focus()}});
